-- Gart: initial schema (D1 / SQLite).
-- Conventions: random text ids (UUIDv4 generated by the Worker), ISO-8601 UTC timestamps.
-- Live game state is NOT stored here; it lives in the GameRoom Durable Object.

PRAGMA foreign_keys = ON;

CREATE TABLE administrators (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  display_name  TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  kdf_params    TEXT NOT NULL CHECK (json_valid(kdf_params)),
  role          TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'editor')),
  disabled      INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE admin_sessions (
  id           TEXT PRIMARY KEY,
  admin_id     TEXT NOT NULL REFERENCES administrators (id) ON DELETE CASCADE,
  token_hash   TEXT NOT NULL UNIQUE,
  expires_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  ip_hash      TEXT,
  user_agent   TEXT,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_admin_sessions_admin ON admin_sessions (admin_id);
CREATE INDEX idx_admin_sessions_expires ON admin_sessions (expires_at);

-- Images are stored in D1 (no R2 by design, see docs/DECISIONS.md D-001).
-- The Worker enforces a small per-image size limit well below D1's row-size limit.
CREATE TABLE uploaded_media (
  id          TEXT PRIMARY KEY,
  mime        TEXT NOT NULL CHECK (mime IN ('image/webp', 'image/png', 'image/jpeg')),
  bytes       INTEGER NOT NULL CHECK (bytes > 0),
  sha256      TEXT NOT NULL,
  data        BLOB NOT NULL,
  uploaded_by TEXT REFERENCES administrators (id) ON DELETE SET NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_uploaded_media_sha ON uploaded_media (sha256);

CREATE TABLE quiz_templates (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  is_system     INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0, 1)),
  settings_json TEXT NOT NULL CHECK (json_valid(settings_json)),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE quizzes (
  id             TEXT PRIMARY KEY,
  title          TEXT NOT NULL,
  description    TEXT NOT NULL DEFAULT '',
  cover_media_id TEXT REFERENCES uploaded_media (id) ON DELETE SET NULL,
  category       TEXT NOT NULL DEFAULT '',
  tags_json      TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(tags_json)),
  difficulty     TEXT CHECK (difficulty IN ('easy', 'medium', 'hard')),
  language       TEXT NOT NULL DEFAULT 'uk',
  template_id    TEXT REFERENCES quiz_templates (id) ON DELETE SET NULL,
  settings_json  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(settings_json)),
  status         TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'archived')),
  created_by     TEXT REFERENCES administrators (id) ON DELETE SET NULL,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_quizzes_status_updated ON quizzes (status, updated_at);

CREATE TABLE questions (
  id             TEXT PRIMARY KEY,
  quiz_id        TEXT NOT NULL REFERENCES quizzes (id) ON DELETE CASCADE,
  position       INTEGER NOT NULL CHECK (position >= 0),
  type           TEXT NOT NULL CHECK (type IN ('single', 'truefalse')),
  text           TEXT NOT NULL,
  image_media_id TEXT REFERENCES uploaded_media (id) ON DELETE SET NULL,
  time_limit_s   INTEGER CHECK (time_limit_s IS NULL OR time_limit_s BETWEEN 5 AND 300),
  points         INTEGER CHECK (points IS NULL OR points BETWEEN 0 AND 10000),
  explanation    TEXT NOT NULL DEFAULT '',
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (quiz_id, position)
);

CREATE TABLE answer_options (
  id             TEXT PRIMARY KEY,
  question_id    TEXT NOT NULL REFERENCES questions (id) ON DELETE CASCADE,
  position       INTEGER NOT NULL CHECK (position BETWEEN 0 AND 3),
  text           TEXT NOT NULL,
  image_media_id TEXT REFERENCES uploaded_media (id) ON DELETE SET NULL,
  is_correct     INTEGER NOT NULL DEFAULT 0 CHECK (is_correct IN (0, 1)),
  UNIQUE (question_id, position)
);

CREATE TABLE game_sessions (
  id                     TEXT PRIMARY KEY,
  quiz_id                TEXT REFERENCES quizzes (id) ON DELETE SET NULL,
  quiz_title             TEXT NOT NULL,
  pin                    TEXT NOT NULL CHECK (length(pin) = 6),
  status                 TEXT NOT NULL CHECK (status IN
    ('CREATED', 'LOBBY', 'QUESTION_ACTIVE', 'QUESTION_RESULTS', 'LEADERBOARD', 'FINISHED', 'CANCELLED')),
  settings_snapshot_json TEXT NOT NULL CHECK (json_valid(settings_snapshot_json)),
  quiz_snapshot_json     TEXT NOT NULL CHECK (json_valid(quiz_snapshot_json)),
  host_admin_id          TEXT REFERENCES administrators (id) ON DELETE SET NULL,
  started_at             TEXT,
  finished_at            TEXT,
  created_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
-- A PIN may be reused only after its previous game has ended.
CREATE UNIQUE INDEX idx_game_sessions_active_pin ON game_sessions (pin)
  WHERE status IN ('CREATED', 'LOBBY', 'QUESTION_ACTIVE', 'QUESTION_RESULTS', 'LEADERBOARD');
CREATE INDEX idx_game_sessions_quiz ON game_sessions (quiz_id);
CREATE INDEX idx_game_sessions_created ON game_sessions (created_at);

CREATE TABLE game_participants (
  id            TEXT PRIMARY KEY,
  game_id       TEXT NOT NULL REFERENCES game_sessions (id) ON DELETE CASCADE,
  nickname      TEXT NOT NULL,
  nickname_key  TEXT NOT NULL,
  avatar        TEXT NOT NULL,
  final_rank    INTEGER,
  total_points  INTEGER NOT NULL DEFAULT 0,
  correct_count INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (game_id, nickname_key)
);
CREATE INDEX idx_game_participants_game ON game_participants (game_id);

CREATE TABLE game_results (
  id                TEXT PRIMARY KEY,
  game_id           TEXT NOT NULL REFERENCES game_sessions (id) ON DELETE CASCADE,
  participant_id    TEXT NOT NULL REFERENCES game_participants (id) ON DELETE CASCADE,
  question_position INTEGER NOT NULL CHECK (question_position >= 0),
  option_id         TEXT NOT NULL,
  is_correct        INTEGER NOT NULL CHECK (is_correct IN (0, 1)),
  points            INTEGER NOT NULL CHECK (points >= 0),
  answer_ms         INTEGER NOT NULL CHECK (answer_ms >= 0),
  UNIQUE (game_id, participant_id, question_position)
);
CREATE INDEX idx_game_results_game ON game_results (game_id);

CREATE TABLE application_settings (
  key        TEXT PRIMARY KEY,
  value_json TEXT NOT NULL CHECK (json_valid(value_json)),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Daily roll-ups of application-measured usage only. Never official Cloudflare figures.
CREATE TABLE usage_metrics (
  day    TEXT NOT NULL,
  metric TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'measured' CHECK (source = 'measured'),
  value  INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (day, metric)
);

CREATE TABLE audit_logs (
  id         TEXT PRIMARY KEY,
  admin_id   TEXT REFERENCES administrators (id) ON DELETE SET NULL,
  action     TEXT NOT NULL,
  entity     TEXT NOT NULL DEFAULT '',
  entity_id  TEXT NOT NULL DEFAULT '',
  meta_json  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(meta_json)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_audit_logs_created ON audit_logs (created_at);
CREATE INDEX idx_audit_logs_admin ON audit_logs (admin_id);
